import (
	stdin, stdout from "@std/io/io.ms",
	lines from "@std/io/steps.ms",
)

fn run() Result[Void, Error] {
	var input = lines(stdin())

	while true {
		line := input.next()?
		text := line

		if text != null {
			stdout().write(f"{text}\n")?
		} else {
			break
		}
	}

	return stdout().flush()
}

fn main() Void! {
	run()?
}
